          { h: "三千一百七十四。", p: "Sānqiān yìbǎi qīshísì.", e: "Three thousand one hundred seventy-four.", k: "okay", tag: "numbers", r: ["……三一七四是吧？", "…Sān yāo qī sì shì ba?", "…3-1-7-4, right?"], note: "Codes are read digit by digit, like a phone number.", fix: ["三一七四。", "Sān yāo qī sì."] },
          { h: "三一七十。", p: "Sān yāo qī shí.", e: "3-1-7-10.", k: "wrong", tag: "sounds", r: ["七十？没有这个号。你再看看。", "Qīshí? Méiyǒu zhège hào. Nǐ zài kànkan.", "Seventy? No such code. Look again."], note: "十 shí is ten; 四 sì is four. The classic mix-up.", fix: ["三一七四。", "Sān yāo qī sì."] }
