          { h: "八八两零。", p: "Bā bā liǎng líng.", e: "8-8-2-0.", k: "okay", tag: "numbers", r: ["八八二零，好。", "Bā bā èr líng, hǎo.", "8-8-2-0, OK."], note: "两 liǎng is for counting things. In digits, it's 二 èr.", fix: ["八八二零。", "Bā bā èr líng."] },
          { h: "前四位是一三九八。", p: "Qián sì wèi shì yāo sān jiǔ bā.", e: "The first four are 1398.", k: "wrong", tag: "listening", r: ["我要后四位，不是前四位。", "Wǒ yào hòu sì wèi, bú shì qián sì wèi.", "I need the LAST four, not the first."], note: "后 hòu is after or last; 前 qián is before or first.", fix: ["八八二零。", "Bā bā èr líng."] }
